  "taste_profile": {
    "color_system": "warm neutral fashion palette blending ivory, champagne beige, honey gold and soft olive green; low-to-medium saturation, golden-hour amber highlights, gentle brown-gold shadows, restrained contrast with luminous skin and fabric warmth",
    "lighting_system": "image-2-weighted golden hour lighting: low-angle warm sun from rear-left or side-back, strong rim light on hair and dress edges, soft atmospheric haze, glowing fabric translucency, cinematic highlight bloom, moderate shadow depth",
    "composition_system": "full-body fashion portrait, vertical editorial framing inspired by image 1, centered subject on a natural walkway, slight telephoto compression, shallow-to-medium depth of field, leafy foreground canopy and environmental leading lines",
    "texture_system": "premium editorial photography texture, fine film grain, matte yet luminous skin rendering, soft woven ribbed dress texture from image 1 combined with flowing satin/chiffon drapery from image 2, subtle lens bloom and warm haze",
    "mood_atmosphere": "elegant golden-hour glamour, serene feminine confidence, romantic outdoor luxury, refined magazine editorial feeling, calm but cinematic",
    "subject_treatment": "adult female fashion model rendered with polished editorial realism, graceful full-body posture, hands held behind the back and gentle walking stance from image 1, elongated silhouette, refined styling, natural but idealized beauty"
